use kuleshov_parity::{executable, hidden, wav};
use std::{
    fs, io,
    path::{Path, PathBuf},
};

/// What the trailer cases read, generated by FFmpeg (no media is committed): two stills of
/// another aspect than the video (so they are cropped, and the landscape one panned) and five
/// seconds of stereo music, shorter than any trailer (so it loops).
const INPUTS: [(&str, &[&str]); 3] = [
    (
        "portrait.jpg",
        &[
            "-f",
            "lavfi",
            "-i",
            "testsrc2=size=1200x1800:rate=1",
            "-frames:v",
            "1",
            "-q:v",
            "2",
        ],
    ),
    (
        "landscape.jpg",
        &[
            "-f",
            "lavfi",
            "-i",
            "testsrc2=size=2400x1200:rate=1",
            "-frames:v",
            "1",
            "-q:v",
            "2",
        ],
    ),
    (
        "music.opus",
        &[
            "-f",
            "lavfi",
            "-i",
            "aevalsrc=0.4*sin(2*PI*220*t)*(0.6+0.4*sin(PI*t))|0.4*sin(2*PI*277*t):s=48000:d=5",
            "-c:a",
            "libopus",
            "-b:a",
            "96k",
        ],
    ),
];

/// Generate the trailer inputs into `dir` with the `ffmpeg` in `tools` and return their paths.
///
/// The encodes are bit-exact (no version strings, no random Ogg serial number), so they are the
/// same on every run with the same FFmpeg build.
///
/// # Errors
/// When FFmpeg cannot be run or fails.
pub fn generate_inputs(tools: &Path, dir: &Path) -> io::Result<Vec<PathBuf>> {
    fs::create_dir_all(dir)?;
    let mut files = Vec::new();
    for (name, args) in INPUTS {
        let file = dir.join(name);
        let output = hidden(&tools.join(executable("ffmpeg")))
            .args(["-v", "error", "-y"])
            .args(args)
            .args(["-fflags", "+bitexact", "-flags", "+bitexact"])
            .arg(&file)
            .output()?;
        if !output.status.success() {
            return Err(io::Error::other(format!(
                "ffmpeg could not make {name}: {}",
                String::from_utf8_lossy(&output.stderr).trim()
            )));
        }
        files.push(file);
    }
    Ok(files)
}

/// A narrator that needs no model: a sine as long as the text takes to read at about 50
/// characters a second, plus half a second, at a pitch that changes with the text.
///
/// Scenes therefore last different times, none a whole number of frames.
///
/// # Errors
/// When `wav` cannot be written.
pub fn tone(text: &str, wav_path: &Path) -> io::Result<()> {
    let chars = text.chars().count();
    #[expect(
        clippy::cast_precision_loss,
        reason = "a text of a few hundred characters"
    )]
    let (seconds, frequency) = (0.5 + chars as f64 / 50.0, 220.0 + (chars % 7) as f32 * 40.0);
    fs::write(wav_path, wav(24_000, frequency, 0.5, seconds, 0.0))
}
